CREATE TABLE skill_sources (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, repository_url TEXT NOT NULL, branch TEXT NOT NULL DEFAULT 'main', enabled BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE skills (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_id UUID NOT NULL REFERENCES skill_sources(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', repository_path TEXT NOT NULL, UNIQUE(source_id, repository_path));
CREATE TABLE installed_skills (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), skill_id UUID NOT NULL UNIQUE REFERENCES skills(id) ON DELETE CASCADE, install_path TEXT NOT NULL, commit_sha TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'installed' CHECK(status IN('installed','disabled','failed')), installed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE agents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', adapter TEXT NOT NULL DEFAULT 'codex', prompt TEXT NOT NULL, workspace_path TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, max_parallel_runs INTEGER NOT NULL DEFAULT 1 CHECK(max_parallel_runs > 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE agent_skills (agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE CASCADE, installed_skill_id UUID NOT NULL REFERENCES installed_skills(id) ON DELETE RESTRICT, PRIMARY KEY(agent_id, installed_skill_id));
CREATE TABLE automation_rules (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, board_id UUID REFERENCES boards(id) ON DELETE CASCADE, trigger_type TEXT NOT NULL, target_column_id UUID REFERENCES workflow_columns(id) ON DELETE CASCADE, agent_id UUID REFERENCES agents(id) ON DELETE SET NULL, enabled BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE automation_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), type TEXT NOT NULL, task_id UUID REFERENCES tasks(id) ON DELETE CASCADE, board_id UUID REFERENCES boards(id) ON DELETE CASCADE, payload JSONB NOT NULL DEFAULT '{}', occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), processed_at TIMESTAMPTZ);
CREATE TABLE agent_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, agent_id UUID NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, rule_id UUID REFERENCES automation_rules(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','failed','cancelled')), prompt_snapshot TEXT NOT NULL, skill_snapshot JSONB NOT NULL DEFAULT '[]', workspace_snapshot TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', error_message TEXT NOT NULL DEFAULT '', started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE agent_run_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), agent_run_id UUID NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE, sequence INTEGER NOT NULL, level TEXT NOT NULL DEFAULT 'info', message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(agent_run_id, sequence));
CREATE INDEX agent_runs_by_task ON agent_runs(task_id, created_at DESC);
